/** Extracts Binary resource URLs from a DocumentReference. */
export function getBinaryResourcesFromDocumentReference(documentRef) {
    if (!documentRef || !Array.isArray(documentRef.content)) return [];
    return documentRef.content
        .map(item => item.attachment?.url)
        .filter(url => typeof url === 'string' && url.includes('Binary/'));
}

/** Wraps a FHIR resource into a displayable message object. */
export function createWrappedMessage({
    sourceType,
    fileType,
    resourceId,
    title,
    resource,
    attachment,
    index
}) {
    return {
        type: sourceType,
        fileType,
        resourceId,
        title,
        date: resource?.date || null,
        sourceDescription: resource?.description || null,
        index,
        ...(sourceType === "DocumentReference" || sourceType === "Media"
            ? { resource }
            : { attachment }),
    };
}

export function toBase64(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => {
            // Remove the prefix "data:<mime-type>;base64,"
            const base64String = reader.result.split(',')[1];
            resolve(base64String);
        };
        reader.onerror = error => reject(error);
    });
}


/** Builds a Communication payload for sending. */
export async function buildCommunicationPayload({
    contextProvider,
    recipients,
    selectedPatient,
    encounter,
    topic,
    priority,
    category,
    about,
    reason,
    anchorReference,
    replyToCommId,
    message,
    selectedDocuments
}) {
    const senderRef = `Practitioner/${contextProvider?.id}`;
    const now = new Date().toISOString();

    // Start with initial about array (deduplicated)
    const aboutSet = new Set(about?.map(a => a.reference) || []);

    const payload = {
        resourceType: "Communication",
        status: "completed",
        sender: { reference: senderRef },
        recipient: recipients.map(r => ({ reference: `${r.resourceType}/${r.id}` })),
        subject: { reference: `Patient/${selectedPatient?.id}` },
        encounter: { reference: `Encounter/${encounter?.id}` },
        topic: {
            coding: [{
                system: "http://example.com/custom-topic-system",
                code: "progress-update",
                display: topic
            }]
        },
        priority: priority || "routine",
        category: [{
            coding: [{
                system: "http://terminology.hl7.org/CodeSystem/communication-category",
                code: category,
                display: category.charAt(0).toUpperCase() + category.slice(1)
            }]
        }],
        about: about ? [...about] : [],
        reasonCode: reason ? [{
            coding: [{
                system: "http://snomed.info/sct",
                code: reason,
                display: reason
            }]
        }] : [],
        ...(anchorReference && { partOf: [{ reference: anchorReference }] }),
        ...(replyToCommId && { inResponseTo: [{ reference: `Communication/${replyToCommId}` }] }),
        payload: [{ contentString: message }],
        sent: now,
        extension: []
    };

    // Helper function to add about reference if not already present
    const addAboutReference = (ref) => {
        if (!aboutSet.has(ref)) {
            payload.about.push({ reference: ref });
            aboutSet.add(ref);
        }
    };

    // Process selected documents
    for (const doc of selectedDocuments) {
        console.log("Selected Documents", selectedDocuments);


        if (doc.resource) {
            addAboutReference(`${doc.resource.resourceType}/${doc.resource.id}`);

        } else if (doc.attachment) {
            try {
                const base64Data = await toBase64(doc.attachment);
                payload.payload.push({
                    contentAttachment: {
                        contentType: doc.attachment.type || "application/octet-stream",
                        title: doc.title,
                        data: base64Data
                    }
                });
            } catch (err) {
                console.error(`❌ Failed to encode attachment ${doc.title}:`, err);
            }
        }
    }

    // Add read-receipt extension if message is sent to others
    const mockMessage = { sender: { reference: senderRef } };
    const isSelf = isSelfMessage(mockMessage, contextProvider?.id);

    if (!isSelf) {
        payload.extension.push({
            url: "http://endpointhealth.ca/fhir/StructureDefinition/read-receipt",
            extension: [
                { url: "user", valueReference: { reference: senderRef } },
                { url: "readAt", valueDateTime: now }
            ]
        });
    }

    return payload;
}

export const hydrateMessage = async ({
    msg,
    selfId,
    store,
    fhirClient
}) => {
    if (msg.meta?.hydrated) {
        console.log("🔁 Already hydrated:", msg.id);
        return msg;
    }
    //console.log("💧 Hydrating message:", msg.id);
    const senderRef = msg.sender?.reference;
    const senderId = senderRef?.split("/")?.pop();
    const isSelf = senderId === selfId;
    const senderName = await resolveName(senderRef, store, fhirClient);
    const content = msg.payload?.find(p => p.contentString)?.contentString || "[No content]";
    const attachments = msg.payload?.filter(p => p.contentAttachment)?.map(p => p.contentAttachment) || [];

    const readReceipts = msg.extension?.filter(ext =>
        ext.url === "http://endpointhealth.ca/fhir/StructureDefinition/read-receipt"
    ) || [];

    const readDetails = await Promise.all(
        readReceipts
            .filter(ext => {
                const readerRef = ext.extension?.find(e => e.url === "user")?.valueReference?.reference;
                const readerId = readerRef?.split("/")?.pop();
                return readerId !== senderId;
            })
            .map(async ext => {
                const userRef = ext.extension?.find(e => e.url === "user")?.valueReference?.reference;
                const readerName = await resolveName(userRef, store, fhirClient);
                const readAt = ext.extension?.find(e => e.url === "readAt")?.valueDateTime;
                return readerName && readAt ? { reader: readerName, readAt } : null;
            })
    );

    const status = isSelf ? (msg.meta?.isPending ? "⏳ ...Sending" : "✅ Sent") : null;

    const enriched = {
        id: msg.id,
        sent: msg.sent,
        sender: senderName || senderRef || "Unknown",
        isSelf,
        content,
        attachments,
        status,
        readDetails: readDetails.filter(Boolean)
    };

    return {
        ...msg,
        meta: {
            ...(msg.meta || {}),
            hydrated: true,
            enrichedData: enriched,
            hydratedAt: new Date().toISOString()
        }
    };
};


