/**
 * Hydrates and dispatches an array of Communication messages directly without searching for redux messages.
 *
 * @param {object[]} messages - Array of raw Communication resources
 * @param {object} contextProvider - Practitioner context
 * @param {object} store - Redux store
 * @param {object} fhirClient - FHIR client instance
 * @param {boolean} isMounted - Component mount flag
 * @param {function} dispatch - Redux dispatch
 * @returns {Promise<object[]>} - Array of hydrated messages
 */
export const hydrateMessageArray = async ({
    messages,
    contextProvider,
    store,
    fhirClient,
    isMounted,
    dispatch
}) => {
    try {
        if (!Array.isArray(messages) || messages.length === 0) {
            console.log("⚠️ No messages provided for hydration");
            return [];
        }

        console.log(`💧 Hydrating ${messages.length} messages from array...`);
        const selfId = contextProvider?.id?.split("/")?.pop();
        const hydratedMessages = [];

        for (const msg of messages) {
            if (!isMounted) {
                console.log("⛔ Aborting hydration — component unmounted.");
                break;
            }

            const hydrated = await hydrateMessage({
                msg,
                selfId,
                store,
                fhirClient
            });

            if (hydrated) {
                hydratedMessages.push(hydrated);
                dispatch(updateHydration({
                    id: hydrated.id,
                    enriched: hydrated.meta.enrichedData
                }));
            }
        }

        return hydratedMessages;
    } catch (err) {
        console.error("🚨 Error hydrating message array:", err);
        throw err;
    }
};


export const hydrateMessages = async ({
    messageIds,
    byId,
    contextProvider,
    store,
    fhirClient,
    isMounted,
    dispatch
}) => {
    try {
        console.log("💧 Starting individual hydration for messages:", messageIds);

        const selfId = contextProvider?.id?.split("/")?.pop();
        const rawMessages = messageIds.map(id => byId?.[id]).filter(Boolean);
        const hydratedMessages = [];

        console.log(`💧 Hydrating ${rawMessages.length} messages individually...`);

        for (const msg of rawMessages) {
            console.log(`💧 Hydrating message ${msg.id}...`);
            if (!isMounted) {
                console.log("⛔ Aborting hydration — component unmounted.");
                break;
            }

            const hydrated = await hydrateMessage({
                msg,
                selfId,
                store,
                fhirClient
            });

            console.log(`💧 Hydrated message ${msg.id}:`, hydrated);

            if (hydrated) {
                hydratedMessages.push(hydrated);
                dispatch(updateHydration({
                    id: hydrated.id,
                    enriched: hydrated.meta.enrichedData
                }));
            }
        }

        return hydratedMessages;
    } catch (err) {
        console.error("🚨 Error hydrating messages individually:", err);
        throw err;
    }
};

