import React, { useEffect, useState } from "react";
import FHIR from "fhirclient";
import "bootstrap/dist/css/bootstrap.min.css";
import BoxContainer from "./BoxContainer";
import CommunicationService from "./services/CommunicationService";
import { loadOrgConfig } from "./configs/loadConfig";
import { Modal, Button } from "react-bootstrap";
import { logEvent } from "./services/logService";
import { buildLoginAuditEvent, buildErrorAuditEvent } from "./services/auditEventBuilder";
import { useDispatch, useSelector, useStore } from "react-redux";
import { setOrgConfig, setAuthToken } from "./slices/configSlice";
import { decodeJWT } from "./utils/jwtUtils";
import { loadSmartStyles } from "./styleLoader";
import { syncProvidersToServer } from "./store/thunks/syncProvidersToServer";

function App() {
  console.log("App component initialized");
  //console.log("API URL:", process.env.REACT_APP_API_URL);

  const dispatch = useDispatch();
  const store = useStore(); // ✅ Access the current Redux store instance
  const orgConfig = useSelector((state) => state.config.orgConfig);
  const [contextPatient, setContextPatient] = useState(null);
  const [contextProvider, setContextProvider] = useState(null);
  const [contextEncounter, setContextEncounter] = useState(null);
  const [error, setError] = useState(null);
  const [showErrorModal, setShowErrorModal] = useState(false);
  const [urlParams, setUrlParams] = useState(null);
  const [jwtData, setJwtData] = useState(null);
  const [iss, setIss] = useState(null);
  const [fhirClient, setFhirClient] = useState(null);
  const [communicationService, setCommunicationService] = useState(null);
  let accessToken = null;

  useEffect(() => {
    console.log("App component initialized");
    console.log("🔗 RAW URL:", window.location.href);

    const searchParams = new URLSearchParams(window.location.search);
    console.log("search params", Object.fromEntries(searchParams.entries()));

    let issParam = searchParams.get("iss");
    let launch = searchParams.get("launch");
    const launchError = searchParams.get("error");
    const errorDescription = searchParams.get("error_description");

    // Handle nested SMART launch parameters inside `app` (used by local launcher)
    const appParam = searchParams.get("app");
    if (appParam && (!issParam || !launch)) {
      try {
        const nestedParams = new URLSearchParams(appParam.split("?")[1]);
        issParam = issParam || nestedParams.get("iss");
        launch = launch || nestedParams.get("launch");
        console.log("🔍 Extracted nested SMART params from `app`:", { issParam, launch });
      } catch (err) {
        console.warn("⚠️ Failed to parse nested SMART params from `app`:", err);
      }
    }

    // Persist SMART launch params across redirect
    if (issParam && launch) {
      sessionStorage.setItem("smart_iss", issParam);
      sessionStorage.setItem("smart_launch", launch);
    } else {
      issParam = sessionStorage.getItem("smart_iss");
      launch = sessionStorage.getItem("smart_launch");
    }

    console.log("🔍 Final SMART Params:");
    console.log("  issParam:", issParam);
    console.log("  launch:", launch);
    console.log("  launchError:", launchError);
    console.log("  errorDescription:", errorDescription);

    function getEnvironmentFromHostname() {
      const host = window.location.hostname;
      if (host.includes("dev.endpointhealth.ca")) return "dev";
      if (host.includes("uat.endpointhealth.ca")) return "uat";
      if (host.includes("launch.endpointhealth.ca")) return "prd";
      if (host === "localhost" || host.endsWith(".local")) return "dev";
      return "dev";
    }

    const environment = getEnvironmentFromHostname();

    if (launchError) {
      const readable = decodeURIComponent(errorDescription || launchError);
      console.log("OAuth launch error:", readable);
      setError(`Authorization failed: ${readable}`);
      setShowErrorModal(true);
      return;
    }

    let accessToken = null;

    const fetchContextData = async () => {
      try {
        const client = await FHIR.oauth2.ready();
        setFhirClient(client);

        const tokenResponse = client?.state?.tokenResponse || {};
        accessToken = tokenResponse.access_token;
        const refreshToken = tokenResponse.refresh_token;
        const idToken = tokenResponse.id_token;

        const decodedAccessToken = accessToken ? decodeJWT(accessToken) : null;
        const decodedIdToken = idToken ? decodeJWT(idToken) : null;

        setJwtData({
          access: decodedAccessToken,
          id: decodedIdToken
        });

        console.log("🔓 Decoded Access Token:", decodedAccessToken);
        console.log("🔓 Decoded ID Token:", decodedIdToken);

        const issuer = decodedIdToken?.iss || issParam || sessionStorage.getItem("smart_iss");
        if (!issuer) {
          console.warn("🚫 Missing issuer — cannot validate origin or load org config");
        } else {
          console.log("✅ Using issuer from ID token or fallback:", issuer);
        }

        const config = loadOrgConfig(issuer);
        console.log("🛠️ Loaded org config from issuer:", config);
        dispatch(setOrgConfig(config));

        if (tokenResponse.smart_style_url) {
          console.log("🎨 Loading SMART styles from:", tokenResponse.smart_style_url);
          loadSmartStyles(tokenResponse.smart_style_url);
        }

        const practitionerId =
          decodedIdToken?.fhirUser?.split("/")[1] ||
          decodedAccessToken?.fhirUser?.split("/")[1] ||
          null;
        const encounterId = tokenResponse.encounter;

        const practitioner = practitionerId
          ? await client.request(`Practitioner/${practitionerId}`)
          : null;
        const patient = await client.patient.read();
        const encounter = encounterId
          ? await client.request(`Encounter/${encounterId}`)
          : null;

        setContextProvider(practitioner);
        setContextPatient(patient);
        if (encounter) setContextEncounter(encounter);

        const auditEvent = buildLoginAuditEvent({
          practitioner,
          patient,
          store
        });
        console.log("AuditEvent to log:", auditEvent);
        console.log("Access Token for logging:", accessToken);
        dispatch(setAuthToken(accessToken));
        logEvent(auditEvent, store).catch((logErr) => {
          console.warn("⚠️ Failed to log audit event:", logErr);
        });
      } catch (error) {
        const rawMessage = error?.message || error.toString();
        console.error("Error Fetching FHIR Data:", rawMessage);
        setError(`FHIR Initialization Error: ${rawMessage}`);
        setShowErrorModal(true);

        const agent = contextProvider
          ? {
            who: {
              reference: `Practitioner/${contextProvider.id}`,
              display:
                contextProvider.name?.[0]?.text ||
                `${contextProvider.name?.[0]?.given?.join(" ")} ${contextProvider.name?.[0]?.family}` ||
                "Unknown"
            },
            requestor: true
          }
          : {
            who: { reference: "Practitioner/unknown", display: "Unknown" },
            requestor: true
          };

        const entity = contextPatient
          ? {
            what: {
              reference: `Patient/${contextPatient.id}`,
              display:
                contextPatient.name?.[0]?.text ||
                `${contextPatient.name?.[0]?.given?.join(" ")} ${contextPatient.name?.[0]?.family}` ||
                "Unknown"
            },
            role: { code: "1", display: "Patient" }
          }
          : {
            what: { reference: "Patient/unknown", display: "Unknown" },
            role: { code: "1", display: "Patient" }
          };

        const auditEvent = buildErrorAuditEvent({
          errorType: "update",
          error: {
            message: rawMessage,
            status: error?.status || error?.response?.status || 500
          },
          agent,
          entity,
          description: "Error updating patient record",
          store
        });

        console.log("AuditEvent for error:", auditEvent);
        console.log("Access Token for logging:", accessToken);
        logEvent(auditEvent, store).catch((logErr) => {
          console.warn("⚠️ Failed to log audit event:", logErr);
        });
      }
    };

    FHIR.oauth2
      .ready()
      .then((client) => {
        console.log("✅ SMART client state:", client?.state);
        const tokenResponse = client?.state?.tokenResponse;
        console.log("✅ Token response:", tokenResponse);

        accessToken = tokenResponse?.access_token;
        const idToken = tokenResponse?.id_token;

        //console.log("✅ Access token:", accessToken);
        //console.log("✅ ID token:", idToken);
        console.log("✅ fhirUser claim:", tokenResponse?.fhirUser);

        if (!accessToken) {
          console.error("❌ No access token returned — token exchange likely failed");
          console.log("🔍 Full token response object:", tokenResponse);
          setError("Token exchange failed — no access token received");
          setShowErrorModal(true);
          return;
        }

        if (!idToken) {
          console.warn("⚠️ No ID token returned — check Keycloak client scopes and mappers");
        }

        fetchContextData();
      })
      .catch(() => {
        console.log("🔁 SMART client not ready — initiating launch");
        if (issParam && launch) {
          console.log("issParam", issParam);
          const redirectUri = window.location.origin;
          console.log("window location href", redirectUri + "/");
          FHIR.oauth2.authorize({
            clientId: "smart-app",
            redirectUri,
            scope: "launch openid fhirUser patient/*.read encounter/*.read communication/*.read offline_access",
            iss: issParam,
            launch,
            aud: issParam,
            completeInTarget: true
          });
        } else {
          console.error("❌ Missing SMART launch parameters");
          setError("Missing SMART launch parameters");
          setShowErrorModal(true);
        }
      });
  }, []);

  useEffect(() => {
    if (!fhirClient) return;
    setCommunicationService(new CommunicationService(fhirClient));
  }, [fhirClient]);

  useEffect(() => {
    const interval = setInterval(() => {
      console.log("⏱️ Dispatching periodic provider sync");
      dispatch(syncProvidersToServer(store));
    }, 10 * 60 * 1000); //every 10 minutes

    return () => clearInterval(interval);
  }, [dispatch]);

  return (
    <div style={{ padding: "0px 5px 5px 5px", fontFamily: "Arial, sans-serif" }}>
      {fhirClient && communicationService && orgConfig ? (
        <BoxContainer
          contextProvider={contextProvider}
          contextPatient={contextPatient}
          contextEncounter={contextEncounter}
          error={error}
          fhirClient={fhirClient}
          communicationService={communicationService}
          orgConfig={orgConfig}
        />
      ) : (
        <div>Loading FHIR Client...</div>
      )}

      <Modal show={showErrorModal} onHide={() => setShowErrorModal(false)} centered>
        <Modal.Header closeButton>
          <Modal.Title>Authorization Error</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <div
            style={{
              whiteSpace: "pre-wrap",
              fontFamily: "monospace",
              fontSize: "0.95rem"
            }}
          >
            {error || "An unexpected authentication error occurred. Please try again."}
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowErrorModal(false)}>
            Dismiss
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}

export default App;